using UnityEngine;
using UnityEngine.SceneManagement;
namespace IronRequiem.Editor
{
 [InitializeOnLoad]public static class CombatLabMenuAuthoring
 {
  const string Queue="Tools/IronRequiem/Requests/rooms-menu.txt",Lab="Assets/IronRequiem/Scenes/CombatTwoRoomsLab.unity",Reports="Tools/IronRequiem/Reports/TwoRooms";static readonly DateTime Loaded=DateTime.UtcNow;
  static CombatLabMenuAuthoring(){EditorApplication.update+=Tick;}
  static void Tick(){if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists(Queue))return;if(new[]{"Assets/IronRequiem/Editor/CombatLabMenuAuthoring.cs","Assets/IronRequiem/Tests/PlayMode/CombatTwoRoomsTests.cs","Assets/IronRequiem/Scripts/Levels/CombatLabMenu.cs"}.Any(p=>File.GetLastWriteTimeUtc(p)>Loaded))return;var operation=File.ReadAllText(Queue).Trim();File.Delete(Queue);try{if(Enumerable.Range(0,SceneManager.sceneCount).Any(i=>SceneManager.GetSceneAt(i).isDirty))throw new InvalidOperationException("Preserving dirty scene");if(operation=="hide-legacy"){var scene=EditorSceneManager.OpenScene(Lab);HideLegacyMenus();EditorSceneManager.SaveScene(scene);File.WriteAllText(Reports+"/menu-black-fixed.txt","Disabled legacy menu Canvas roots in lab instances; source prefabs preserved.");}else Build();File.WriteAllText("Tools/IronRequiem/Requests/two-rooms.txt","test");}catch(Exception e){File.WriteAllText(Reports+"/menu-error.txt",e.ToString());Debug.LogException(e);}}
  static RectTransform Rect(GameObject go,Vector2 size,Vector2 position){var r=go.GetComponent<RectTransform>();r.anchorMin=r.anchorMax=new Vector2(.5f,.5f);r.sizeDelta=size;r.anchoredPosition=position;return r;}
  static GameObject Panel(Transform root,string name){var go=new GameObject(name,typeof(RectTransform),typeof(UnityEngine.UI.Image));go.transform.SetParent(root,false);var r=go.GetComponent<RectTransform>();r.anchorMin=Vector2.zero;r.anchorMax=Vector2.one;r.offsetMin=r.offsetMax=Vector2.zero;go.GetComponent<UnityEngine.UI.Image>().color=new Color(.025f,.045f,.065f,.98f);return go;}
  static void Label(Transform root,string name,string text,Vector2 pos,int size){var go=new GameObject(name,typeof(RectTransform));go.transform.SetParent(root,false);Rect(go,new Vector2(850,110),pos);var label=go.AddComponent<TextMeshProUGUI>();label.text=text;label.font=TMP_Settings.defaultFontAsset;label.fontSize=size;label.alignment=TextAlignmentOptions.Center;label.raycastTarget=false;}
  static UnityEngine.UI.Button Button(Transform root,string name,string text,float y){var go=new GameObject(name,typeof(RectTransform),typeof(UnityEngine.UI.Image),typeof(UnityEngine.UI.Button));go.transform.SetParent(root,false);Rect(go,new Vector2(380,64),new Vector2(0,y));go.GetComponent<UnityEngine.UI.Image>().color=new Color(.12f,.32f,.40f);var button=go.GetComponent<UnityEngine.UI.Button>();Label(go.transform,"Caption",text,Vector2.zero,26);return button;}
  static void HideLegacyMenus(){foreach(var menu in UnityEngine.Object.FindObjectsByType<Unity.FPS.UI.InGameMenuManager>(FindObjectsInactive.Include,FindObjectsSortMode.None)){menu.enabled=false;if(menu.MenuRoot)menu.MenuRoot.SetActive(false);PrefabUtility.RecordPrefabInstancePropertyModifications(menu);if(menu.MenuRoot)PrefabUtility.RecordPrefabInstancePropertyModifications(menu.MenuRoot);}}
  static void Build(){var scene=EditorSceneManager.OpenScene(Lab);HideLegacyMenus();var old=UnityEngine.Object.FindAnyObjectByType<CombatLabMenu>();if(old)throw new InvalidOperationException("Menu already exists");var canvas=new GameObject("CombatLabMenu",typeof(Canvas),typeof(UnityEngine.UI.CanvasScaler),typeof(UnityEngine.UI.GraphicRaycaster));canvas.GetComponent<Canvas>().renderMode=RenderMode.ScreenSpaceOverlay;canvas.GetComponent<Canvas>().sortingOrder=200;var scaler=canvas.GetComponent<UnityEngine.UI.CanvasScaler>();scaler.uiScaleMode=UnityEngine.UI.CanvasScaler.ScaleMode.ScaleWithScreenSize;scaler.referenceResolution=new Vector2(1920,1080);scaler.matchWidthOrHeight=.5f;var main=Panel(canvas.transform,"MainPanel");var death=Panel(canvas.transform,"DeathPanel");Label(main.transform,"Title","IRON REQUIEM",new Vector2(0,170),52);Label(main.transform,"Subtitle","LABORATORIO · DOS ARENAS",new Vector2(0,90),24);Label(death.transform,"Title","HAS MUERTO",new Vector2(0,150),48);var menu=canvas.AddComponent<CombatLabMenu>();menu.Configure(UnityEngine.Object.FindAnyObjectByType<PlayerCharacterController>(),main,death);UnityEventTools.AddPersistentListener(Button(main.transform,"PlayButton","JUGAR · CUARTO 1",-35).onClick,menu.BeginGame);UnityEventTools.AddPersistentListener(Button(death.transform,"RestartButton","REINICIAR · CUARTO 1",10).onClick,menu.RestartFromFirstRoom);UnityEventTools.AddPersistentListener(Button(death.transform,"MenuButton","VOLVER AL MENÚ",-80).onClick,menu.ReturnToMainMenu);death.SetActive(false);EditorSceneManager.SaveScene(scene);var list=EditorBuildSettings.scenes.ToList();if(!list.Any(s=>s.path==Lab)){list.Add(new EditorBuildSettingsScene(Lab,true));EditorBuildSettings.scenes=list.ToArray();}File.WriteAllText(Reports+"/menu-build.txt","Lab-only Canvas/buttons and death panel. Existing pause manager disabled only in lab. Scene appended to build list for full reload; previous order retained. Mobile enemies use existing PatrolPath toward player, turret fixed. No global AI/stat/input changes.");}
 }
}
